// lib/logo-ims-costuras.ts
//
// Logo da IMS Costuras, embutida como texto (base64) — assim o
// recibo nunca corre risco de gerar sem ela por causa de um caminho
// de arquivo que não existe no ambiente do servidor.
const LOGO_IMS_COSTURAS_BASE64 =
  ''

export function logoImsCosturasBuffer() {
  return Buffer.from(LOGO_IMS_COSTURAS_BASE64, 'base64')
}